(ns metabase.metabot.tools.autogen-dashboard
  "Autogenerated dashboard tool wrappers."
  (:require
   [clojure.string :as str]
   [metabase.api.common :as api]
   [metabase.metabot.agent.streaming :as streaming]
   [metabase.metabot.db :as metabot.db]
   [metabase.metabot.scope :as scope]
   [metabase.metabot.tools.core :as tools]
   [metabase.metabot.tools.shared :as shared]
   [metabase.util.log :as log]
   [metabase.util.malli :as mu]))

(set! *warn-on-reflection* true)

;;; Source Resolution

(tools/defrecoverable invalid-source!
  "The call set no source, or more than one."
  {:payload [:map {:closed true}]}
  [_]
  {:message  "Set exactly one of `table_id`, `model_id`, `metric_id`, `query_id` or `report_id` in `source`."
   :recovery []})

(tools/defrecoverable unavailable-source!
  "The user can read the source, but it is in the trash, or it is a table that is gone from its database."
  {:payload [:map {:closed true}
             [:kind [:enum :table :model :metric :question]]
             [:id   :int]]}
  [{:keys [kind id]}]
  {:message  (str (str/capitalize (name kind)) " " id
                  (if (= :table kind)
                    " is no longer in its database."
                    " is in the trash."))
   :recovery [{:uses #{"search"}
               :text "Call `search` to find another source and use an id from the results."}]})

(defn- readable-source
  "The `kind` entity with `id` and its X-ray path, if the current user can read it and it is still in use."
  [kind id]
  (let [entity (tools/with-entity {:kind kind :id id}
                 (api/read-check (if (= :table kind)
                                   (metabot.db/table id)
                                   (metabot.db/card-of-type id kind))))]
    (when (or (:archived entity) (false? (:active entity)))
      (unavailable-source! {:kind kind :id id}))
    {:entity entity
     :path   (str "/auto/dashboard/" (name kind) "/" id)}))

(defn- resolve-source
  "Resolve the source entity from the provided source parameters.
  Returns the entity to analyze and the path for navigation."
  [{:keys [table_id model_id metric_id query_id report_id] :as source} memory]
  (when-not (= 1 (count (remove nil? (vals source))))
    (invalid-source! {}))
  (cond
    table_id  (readable-source :table table_id)
    model_id  (readable-source :model model_id)
    metric_id (readable-source :metric metric_id)
    report_id (readable-source :question report_id)

    query_id
    ;; For query_id, we need to resolve from memory
    (let [queries-state (get-in memory [:state :queries] {})
          query (get queries-state query_id)]
      (when-not query
        (throw (ex-info (str "Query not found in memory with ID: " query_id
                             ". Available queries: [" (str/join ", " (keys queries-state)) "]")
                        {:agent-error? true
                         :query-id query_id
                         :available-queries (keys queries-state)})))
      ;; For queries, we create a transient card-like structure
      {:entity {:dataset_query query}
       :path (str "/auto/dashboard/adhoc/" query_id)})))

;;; Response Messages

(def ^:private response-messages
  ["Ok, here is a dashboard that may answer it for you."
   "I've created a dashboard that may answer your question."
   "Here is a dashboard that may help you with your question."
   "I've generated a dashboard with insights about your data."])

(defn- random-response-message []
  (rand-nth response-messages))

;;; Main Tool Implementation

(defn create-autogenerated-dashboard
  "Create an auto-generated dashboard using Metabase's X-ray feature.

  X-ray builds complete dashboards with multiple visualizations that showcase
  different aspects of your data - distributions, breakdowns by categories,
  trends over time, and relationships between fields.

  Parameters:
  - source: Map specifying what to analyze. One of:
    - {:table_id 123} - Create dashboard for a table
    - {:model_id 456} - Create dashboard for a model
    - {:metric_id 789} - Create dashboard for a metric
    - {:query_id \"abc\"} - Create dashboard for query results
    - {:report_id 101} - Create dashboard for an existing report/question
  - memory-atom: Atom containing agent memory (for query resolution)

  Returns map with:
  - :structured-output - Message and dashboard info
  - :data-parts - Dashboard `generated_entity` part for the frontend
  - :instructions - Guidance for the LLM on how to respond"
  [{:keys [source memory-atom]}]
  (log/info "Creating autogenerated dashboard" {:source source})

  (let [memory                 (when memory-atom @memory-atom)
        {:keys [entity path]}  (resolve-source source memory)
        title                  (or (:display_name entity) (:name entity) "Dashboard")
        response-message       (str (random-response-message) "\n\nLet me know if you need anything else.")]
    ;; Note: The actual automagic analysis happens on navigation to the /auto/dashboard/... URL
    ;; The frontend handles rendering the X-ray dashboard

    (log/info "Autogenerated dashboard created" {:path path})
    {:structured-output {:message response-message
                         :path    path}
     :data-parts        [(streaming/dashboard-entity-part {:title title :url path})]
     :instructions      "The dashboard has been created and the user has been navigated to view it. Briefly acknowledge this (1 sentence) and stop. Do not describe the dashboard contents."}))

(def ^:private autogen-dashboard-schema
  [:map {:closed true}
   [:source [:map {:closed true}
             [:table_id {:optional true} [:maybe :int]]
             [:model_id {:optional true} [:maybe :int]]
             [:metric_id {:optional true} [:maybe :int]]
             [:query_id {:optional true} [:maybe :string]]
             [:report_id {:optional true} [:maybe :int]]]]])

(mu/defn ^{:tool-name    "create_autogenerated_dashboard"
           :scope        scope/agent-dashboard-create}
  create-autogenerated-dashboard-tool
  "Create an automatically generated dashboard using Metabase's X-ray feature.

  X-ray builds complete dashboards with multiple visualizations that showcase
  different aspects of your data - distributions, breakdowns by categories,
  trends over time, and relationships between fields.

  Specify one source type:
  - table_id: Create dashboard for a table
  - model_id: Create dashboard for a model
  - metric_id: Create dashboard for a metric
  - query_id: Create dashboard for query results from this conversation
  - report_id: Create dashboard for an existing report/question"
  [{:keys [source]} :- autogen-dashboard-schema]
  (let [result (create-autogenerated-dashboard
                {:source source
                 :memory-atom shared/*memory-atom*})
        structured (:structured-output result)
        data-parts (:data-parts result)]
    (cond-> {:output            (:message structured)
             :structured-output structured
             :instructions      (:instructions result)}
      (seq data-parts) (assoc :data-parts data-parts))))
